#ifndef KEST_VM_H
#define KEST_VM_H

#include "value.h"


// What this machine has said. A host reads it with `kest_report`; the command
// line wants the set rather than a rendering, because it sorts what running
// found together with what compiling did.
KestDiags *kest_runtime_said(KestRuntime *runtime);

// A machine of its own, in an arena of its own. It takes nothing from the
// build's arena: what a machine is made of goes when the machine goes, and
// what it says goes on saying it, because a diagnostic is written where the
// build's are. See D574.
// `walked` is what a walk of the whole program said, which the build works out
// once and every machine is handed: a machine sizes itself from it and holds
// every call into the host against it, and it is the same answer for every
// machine a build starts. See D607.
// The arena is the machine's and is handed in rather than taken here, because
// the machine's report has to live in it and the report exists before the
// machine does. Taking it from the build's arena instead is one bump pointer
// written by every thread that starts a machine, which is what the reference
// says a host may do. See D1071.
KestRuntime *kest_runtime_new(KestArena *own, KestModule *stamped,
                              const KestHost *host, KestDiags *diags,
                              const KestLimits *limits,
                              const KestWalk *walked);
bool kest_runtime_free(KestRuntime *runtime);

// The two doors a file this project's other backend wrote calls, and the only
// two. They are here rather than in the public header because what calls them
// is this project's own output rather than somebody's host: a generated file
// is compiled beside the library it was generated by, and the day it is not,
// the thing to write is a door a host can hold a version against. See D1094.

// Binding a body the host's compiler compiled to the chunk it was written
// from. `index` is where the body is in the module, which is what the
// generated C names it by; `symbol` is held against what is there, because a
// generated file and a program that has moved on since are two programs, and
// binding by number alone puts one body's C under another body's name.
// Answers false when there is nothing at that index, when the name there is
// another, or when that body is already bound.
bool kest_native_at(KestRuntime *runtime, uint32_t index, const char *symbol,
                    KestNativeBody body);

// The bytes of one of an array, after the two things the machine asks before
// it reads or writes one: that the handle is an array rather than something
// else or a lend the host has taken back, and that the index is inside it.
// `offset` is how far into an element a field path reached, which the
// resolved form works out while compiling and which a generated file writes
// down. NULL when it refused, and it has said why at `where` -- in the same
// words, with the same code, as the instruction that does this. What a
// generated file does with the bytes is move them itself: which piece sits
// where is known while compiling, and the walk over a layout that the machine
// does for every element is a third of `bench/rules.kest` (D1028). See D1095.
unsigned char *kest_elem_at(KestRuntime *runtime, KestValue handle,
                            int64_t index, uint16_t offset, uint32_t where);

// How many there are in one, refused the way the machine refuses it: a host
// asking the same question through `kest_array_length` is answered nought for
// a handle that is not an array, because a host may ask about anything and a
// program may not. Answers false when it refused. See D1095.
bool kest_elem_count(KestRuntime *runtime, KestValue handle, uint32_t where,
                     int64_t *into);

// Making a run of elements: what `array(n, v)` does, and what the instruction
// of that name does, because it calls this. What a caller hands over is where
// its own operands are, which is on the machine's stack -- a body that can
// reach the heap lives there (D1098) -- so there is nothing to tell the
// collector about: the walk it starts with reaches them already. `where` is
// the operation in the source, and a refusal says so at that line whichever
// engine ran it. See D1099.
bool kest_array_new(KestRuntime *runtime, uint16_t layout, int64_t count,
                    const KestValue *fill, uint32_t where, KestValue *into);

// One more on the end of a run of them: what `push` does, and what the
// instruction of that name does, because it calls this. See D1099.
bool kest_array_push(KestRuntime *runtime, KestValue handle, uint16_t layout,
                     const KestValue *value, uint32_t where);

// One taken out of the middle of a run of them: what `take` does after the
// element has been read, and what the instruction of that name does, because
// it calls this. What is after it keeps its order, which is the whole
// difference between a run of elements and a store. See D1099.
bool kest_array_remove(KestRuntime *runtime, KestValue handle, int64_t index,
                       uint32_t where);

// A store and what a program asks of one, each what the instruction of that
// name does and each called by it. A store keeps what it holds as slots
// rather than as packed bytes, so none of these walks a layout: what moves is
// a run of slots the width the shape is. `which` is a reference as the
// program holds one -- a place and the stamp it was handed out with -- and a
// reference to a place that has been given back reads as nothing rather than
// as whatever is there now. See D1102.
bool kest_store_new(KestRuntime *runtime, uint16_t layout, int64_t room,
                    uint32_t where, KestValue *into);
bool kest_store_add(KestRuntime *runtime, KestValue handle, uint16_t stride,
                    const KestValue *value, uint32_t where, int64_t *into);
bool kest_store_get(KestRuntime *runtime, KestValue handle, int64_t which,
                    uint16_t stride, KestValue *into, uint32_t where);
bool kest_store_set(KestRuntime *runtime, KestValue handle, int64_t which,
                    uint16_t stride, const KestValue *value, uint32_t where,
                    bool *was);
bool kest_store_remove(KestRuntime *runtime, KestValue handle, int64_t which,
                       uint32_t where, bool *was);
bool kest_store_count(KestRuntime *runtime, KestValue handle, uint32_t where,
                      int64_t *into);
bool kest_store_ref(KestRuntime *runtime, KestValue handle, int64_t index,
                    uint32_t where, int64_t *into);
bool kest_store_seek(KestRuntime *runtime, KestValue handle, int64_t from,
                     uint32_t where, int64_t *found);

// What a piece of text hashes to, what a value of a shape hashes to, and
// whether two values of a shape are the same value. All three are answers the
// machine has and the folder has, written once each and called from both
// (D668): a generated file that worked them out again would be a third answer
// the day any of them moved. `layout` is which of the module's shapes the
// value is. See D1097.
int64_t kest_text_hash(const char *bytes, int64_t length);
int64_t kest_value_hash(KestRuntime *runtime, uint16_t layout,
                        const KestValue *slots);
bool kest_value_same(KestRuntime *runtime, uint16_t layout,
                     const KestValue *left, const KestValue *right);

// Where one piece of text stands to another: below nought, nought, or above,
// the way the bytes stand, which is an order that is the same everywhere
// rather than one that depends on where the program is run (D021). How far it
// had to read comes back in `read`, because what comparing costs is how far it
// got and the machine charges for that -- two long pieces that differ in the
// first byte are cheap and two that are the same are not. A generated file
// passes nothing for `read`: it has no budget to charge. See D950 and D1103.
int64_t kest_text_order(const char *left, int64_t left_length,
                        const char *right, int64_t right_length,
                        int64_t *read);

// The five reads into a piece of text that do not make one: the byte at a
// place, a cut, the rest from a place, whether a needle sits at a place, and
// where one is first found. None of them reaches the heap -- a cut is a place
// inside what it was cut from and how many bytes of it (D964) -- so a body
// that only reads text keeps its slots in C locals. Each says what the
// instruction of that name says when it refuses, in the instruction's own
// words: two engines that put a bounds failure differently are two languages,
// and the check that runs both reads the words. See D1104.
bool kest_text_at(KestRuntime *runtime, const char *bytes, int64_t length,
                  int64_t index, uint32_t where, int64_t *into);
bool kest_text_cut(KestRuntime *runtime, const char *bytes, int64_t length,
                   int64_t from, int64_t count, uint32_t where,
                   const char **at, int64_t *many);
bool kest_text_rest(KestRuntime *runtime, const char *bytes, int64_t length,
                    int64_t from, uint32_t where, const char **at,
                    int64_t *many);
bool kest_text_matches(KestRuntime *runtime, const char *bytes, int64_t length,
                       int64_t at, const char *needle, int64_t needle_length,
                       uint32_t where, int64_t *into);
bool kest_text_find(KestRuntime *runtime, const char *bytes, int64_t length,
                    const char *needle, int64_t needle_length, int64_t from,
                    uint32_t where, int64_t *at, int64_t *found);

// Which of the five ways a value is written as text, for the door below. A
// number with a sign and one without are written differently and a narrow
// float is written to the places a narrow float has, so what is being written
// has to come with it: the backend reads it off the type the way the machine
// reads it off the instruction.
typedef enum {
    KEST_TEXT_OF_INT,
    KEST_TEXT_OF_UNSIGNED,
    KEST_TEXT_OF_REAL,
    KEST_TEXT_OF_NARROW,
    KEST_TEXT_OF_BOOL,
} KestTextOf;

// The four that make text, which is the half of it that reaches the heap and
// so the half a body promising `no.alloc` never gets to: a value written out,
// a shape or a set of bits written out, pieces joined, and a run of bytes
// become text. Each leaves two slots -- what it is made of and how many bytes
// that is -- and each says what the instruction of that name says when there
// is no room for it. See D1104.
bool kest_text_of(KestRuntime *runtime, uint8_t how, KestValue value,
                  uint32_t where, KestValue *into);
bool kest_text_of_value(KestRuntime *runtime, uint16_t layout,
                        const KestValue *slots, uint32_t where,
                        KestValue *into);
bool kest_text_join(KestRuntime *runtime, const KestValue *pieces,
                    uint16_t count, uint32_t where, KestValue *into);
bool kest_text_from(KestRuntime *runtime, KestValue handle, uint32_t where,
                    KestValue *into);

// A whole piece of text onto a run of bytes, and the two appends that answer
// rather than grow. `fit` and `fit.text` are what a body under a promise to
// reach no heap may do: all of it goes in or none of it does, and what comes
// back says which (D940). `append.text` is the loop a program used to write
// taken into one move (D1068).
bool kest_array_fit(KestRuntime *runtime, KestValue handle, uint16_t layout,
                    const KestValue *value, uint32_t where, int64_t *put);
bool kest_array_push_text(KestRuntime *runtime, KestValue handle,
                          uint16_t layout, const char *bytes, int64_t length,
                          uint32_t where);
bool kest_array_fit_text(KestRuntime *runtime, KestValue handle,
                         const char *bytes, int64_t length, uint32_t where,
                         int64_t *put);

// And the four left of what a run of elements does: room made for what is
// coming, everything taken out, the last one taken off, and a run written out
// in the program. `room` is the one that answers about a store as well, which
// is the one instruction in this language that looks at what it was handed to
// decide which of two things it is about.
bool kest_array_room(KestRuntime *runtime, KestValue handle, uint16_t layout,
                     int64_t wanted, uint32_t where);
bool kest_array_clear(KestRuntime *runtime, KestValue handle, uint32_t where);
bool kest_array_pop(KestRuntime *runtime, KestValue handle, uint32_t where,
                    unsigned char **at);
bool kest_array_written(KestRuntime *runtime, uint16_t layout, uint16_t count,
                   const KestValue *values, uint32_t where, KestValue *into);

// A body the machine runs, entered from one the host's compiler compiled.
// This is what makes the two engines one program rather than two halves that
// can only call inwards: a compiled body can call anything, and what it calls
// does not have to have been compiled. The caller has already asked
// `kest_native_room` for room and for the ledger frame, so the frame this
// runs in is the one that is already there -- the machine writes a real frame
// over the ledger one, in the same place, and what a fault says about the
// call is the same either way. `handed` is how many slots of arguments are at
// `base`, and how many came back is left in `gave`. See D1105.
bool kest_call_body(KestRuntime *runtime, uint32_t which, KestValue *base,
                    uint16_t handed, uint16_t *gave);

// And a call through a function value, which is the same thing with what it
// enters decided while it runs. The three questions the machine asks before
// it enters one are asked here in the machine's own words: whether the value
// names a function at all, whether that function is of the shape the call
// was written against, and whether it keeps the promises the body making the
// call made. Only then is it entered -- as C where it was compiled, and
// through `kest_call_body` where it was not. See D1107.
bool kest_call_value(KestRuntime *runtime, KestValue what, KestValue *base,
                     uint16_t handed, uint16_t coming_back, uint32_t where,
                     uint16_t *gave);

// What a door is told when the machine is what asked it. A body the host's
// compiler compiled knows where in the source it is and hands that over; the
// machine knows which instruction it is running, and turning one into the
// other is a walk over the whole body (`kest_chunk_origin`) that only matters
// if something refuses. So the machine hands this over instead and the walk
// happens on the way to the message, which is the one time the answer is
// wanted. It was sixteen per cent of a gameplay workload. See D1117.
#define KEST_WHERE_RUNNING 0xffffffffu

// Working memory opened and put back. A `scratch { }` block is a block of the
// heap that is handed back whole when the block ends, however the block ends
// -- which is what makes it the one way a body can make something and pay
// nothing for it afterwards. `into` comes back holding which block it is, and
// closing one closes everything opened inside it. See D1119.
bool kest_region_open(KestRuntime *runtime, uint32_t where, int64_t *into);
bool kest_region_close(KestRuntime *runtime, int64_t was, uint32_t where);

// One of a fixed run of slots in the frame, at an index worked out while it
// runs: whether the index is one of them. The machine's own sentence, because
// two engines that put a bounds failure differently are two languages. See
// D1109.
bool kest_run_at(KestRuntime *runtime, int64_t index, uint32_t count,
                 uint32_t where);

// The ledger of a machine, read once by a body the host's compiler compiled
// that makes calls: what that body then writes for each call is what
// `kest_native_room` writes, and the two are the same sequence because one of
// them is the other written out. False for a machine with no program.
// See D1122.
bool kest_ledger(KestRuntime *runtime, KestLedger *into);

// And what a call says when there is no room for it: too deep, or past the
// end of the slots. Answers false, so a body can give back what it gives
// back. `deep` says which of the two it is.
bool kest_native_crowded(KestRuntime *runtime, uint32_t which, uint32_t where,
                         bool deep);

// A crossing into the host. Everything the boundary asks is behind this door
// -- what the declaration says against what was moved, how far in a host is
// being called from against what it was measured for, whether what it bound
// is still there, whether it did what it was asked, whether it kept a promise
// made on its behalf, and what it wrote back -- so the machine's instruction
// and a body the host's compiler compiled cross the same way. The arguments
// are at `base` and the answer goes over them, which is the convention a call
// in this language uses everywhere. See D1108.
bool kest_call_host(KestRuntime *runtime, uint16_t index, KestValue *base,
                    uint16_t argument_slots, uint16_t result_slots,
                    uint32_t where);

// What a body written in C says when it stops. `offset` is where in the source
// it was, which the resolved form carries and the C keeps beside the operation
// it came from, so a refusal from a compiled body is reported where the same
// refusal from the machine is -- with the same code, the same line, and the
// calls under it. Answers false, so a body can give back what this gives back.
bool kest_native_stopped(KestRuntime *runtime, uint32_t offset,
                         const char *code, const char *message);

#endif
